// maxUploadBytes bounds a browser upload. The complete Garmin export is
// several GB and belongs into the import folder instead.
const maxUploadBytes = 256 << 20

type importPageData struct {
	ImportDir string
	Job       *ImportJob
}

func (s *server) importPage(w http.ResponseWriter, r *http.Request) {
	s.render(w, r, "import.html", "import", importPageData{ImportDir: s.ImportDir, Job: s.Jobs.Last()})
}

func (s *server) importStatus(w http.ResponseWriter, r *http.Request) {
	s.renderFragment(w, fragmentImportStatus, s.Jobs.Last())
}

// importUpload stores the uploaded files in a temporary folder and imports
// them in the background; the response is the job status fragment.
func (s *server) importUpload(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, maxUploadBytes)
	mr, err := r.MultipartReader()
	if err != nil {
		http.Error(w, "Ungültiger Upload", http.StatusBadRequest)
		return
	}
	if err := os.MkdirAll(s.TempDir, 0o750); err != nil {
		s.serverError(w, "create temp dir", err)
		return
	}
	dir, err := os.MkdirTemp(s.TempDir, "upload-")
	if err != nil {
		s.serverError(w, "create upload dir", err)
		return
	}
	n, err := saveUploads(mr, dir)
	if err != nil || n == 0 {
		os.RemoveAll(dir)
		msg := "Keine .fit- oder .zip-Datei ausgewählt."
		var tooLarge *http.MaxBytesError
		if errors.As(err, &tooLarge) {
			msg = fmt.Sprintf("Upload größer als %d MB. Große Exporte bitte über den Import-Ordner einlesen.", maxUploadBytes>>20)
		} else if err != nil {
			s.Logger.Warn("upload failed", "err", err)
			msg = "Upload fehlgeschlagen."
		}
		w.WriteHeader(http.StatusBadRequest)
		s.renderFragment(w, fragmentImportStatus, &ImportJob{Error: msg})
		return
	}
	label := fmt.Sprintf("Upload (%d Datei%s)", n, map[bool]string{true: "", false: "en"}[n == 1])
	s.startImport(w, label, dir, func() { os.RemoveAll(dir) })
}

// importFolder imports everything in the configured drop folder.
func (s *server) importFolder(w http.ResponseWriter, r *http.Request) {
	if err := os.MkdirAll(s.ImportDir, 0o755); err != nil {
		s.serverError(w, "create import dir", err)
		return
	}
	s.startImport(w, "Ordner "+s.ImportDir, s.ImportDir, nil)
}

func (s *server) startImport(w http.ResponseWriter, label, root string, cleanup func()) {
	err := s.Jobs.Start(label, func(ctx context.Context, report func(importer.Result)) error {
		if _, err := s.Importer.ImportPath(ctx, root, report); err != nil {
			return err
		}
		// A Garmin export also holds health data as JSON next to the FIT files.
		hs, err := health.ImportPath(ctx, s.Store, root)
		switch {
		case err != nil:
			s.Jobs.Note("Gesundheitsdaten konnten nicht gelesen werden: " + err.Error())
		case hs.Days > 0:
			s.Jobs.Note(fmt.Sprintf("Gesundheitsdaten: %d Tage aus %d Dateien übernommen.", hs.Days, hs.Files))
		}
		return nil
	}, cleanup)
	if errors.Is(err, ErrJobRunning) {
		if cleanup != nil {
			cleanup()
		}
		w.WriteHeader(http.StatusConflict)
	}
	s.renderFragment(w, fragmentImportStatus, s.Jobs.Last())
}

var unsafeName = regexp.MustCompile(`[^A-Za-z0-9._-]+`)

// saveUploads writes .fit and .zip parts to dir. File names are sanitized
// and prefixed with a counter; the client-supplied name never becomes a path.
func saveUploads(mr *multipart.Reader, dir string) (int, error) {
	n := 0
	for {
		part, err := mr.NextPart()
		if errors.Is(err, io.EOF) {
			return n, nil
		}
		if err != nil {
			return n, err
		}
		name := filepath.Base(part.FileName())
		ext := strings.ToLower(filepath.Ext(name))
		if part.FormName() != "files" || (ext != ".fit" && ext != ".zip") {
			part.Close()
			continue
		}
		n++
		safe := fmt.Sprintf("%03d_%s", n, unsafeName.ReplaceAllString(strings.TrimSuffix(name, filepath.Ext(name)), "_")+ext)
		if err := writeFile(filepath.Join(dir, safe), part); err != nil {
			part.Close()
			return n, err
		}
		part.Close()
	}
}

func writeFile(path string, r io.Reader) error {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o640)
	if err != nil {
		return err
	}
	if _, err := io.Copy(f, r); err != nil {
		f.Close()
		return err
	}
	return f.Close()
}
